import React, { forwardRef, useContext, useRef } from 'react';
import { useIntl } from 'react-intl';

import Breakpoints from '@dynatrace/strato-design-tokens/breakpoints-js';

import { PageIndexSelect } from './PageIndexSelect.js';
import { PageSizeSelect } from './PageSizeSelect.js';
import { PrevNextButtons } from './PrevNextButtons.js';
import { useBreakpoint } from '../../../core/hooks/useBreakpoint.js';
import { _useControllableState } from '../../../core/hooks/useControllableState.js';
import type { AriaLabelingProps } from '../../../core/types/a11y-props.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { TablePaginationContext } from '../../contexts/TablePaginationContext.js';
import {
  DEFAULT_PAGINATION_PAGE_INDEX,
  DEFAULT_PAGINATION_PAGE_SIZE,
} from '../constants.js';
import { dataTableMessages } from '../messages.js';

// #region Types
export type PaginationProps = PaginationPropsBase &
  (PaginationPageIndexControlledProps | PaginationPageIndexUncontrolledProps) &
  (PaginationPageSizeControlledProps | PaginationPageSizeUncontrolledProps) &
  (PaginationClientSideProps | PaginationServerSideProps);

export interface PaginationPropsBase extends AriaLabelingProps {
  /**
   * The element's unique identifier. See [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/id).
   */
  id?: string;
  /**
   * Test id used for matching the pagination container.
   */
  'data-testid'?: string;
  /** Callback for page changes (exposes pageSize and pageIndex). */
  onPageChange?: (pageSize: number, pageIndex: number) => void;
}

export type PaginationPageIndexUncontrolledProps = {
  /**
   * Initial page index in an uncontrolled scenario.
   * @defaultValue 0
   */
  defaultPageIndex?: number;
  /** Current page index in a controlled scenario. */
  pageIndex?: never;
  /** Called when the page index changes. Provides the changed page index along with the underlying trigger. */
  onPageIndexChange?: (
    pageIndex: number,
    trigger?: 'user' | 'internal',
  ) => void;
};

export type PaginationPageIndexControlledProps = {
  /**
   * Initial page index in an uncontrolled scenario.
   * @defaultValue 0
   */
  defaultPageIndex?: never;
  /** Current page index in a controlled scenario. */
  pageIndex: number;
  /** Called when the page index changes. Provides the changed page index along with the underlying trigger. */
  onPageIndexChange: (pageIndex: number, trigger?: 'user' | 'internal') => void;
};

export interface PaginationPageSizeUncontrolledProps {
  /**
   * Default number of rows per page (uncontrolled).
   * @defaultValue 10
   */
  defaultPageSize?: number;
  /** Number of rows per page (controlled) */
  pageSize?: never;
  /** Handler that is called when the page size changes. */
  onPageSizeChange?: (pageSize: number) => void;
}

export interface PaginationPageSizeControlledProps {
  /**
   * Default number of rows per page (uncontrolled).
   * @defaultValue 10
   */
  defaultPageSize?: never;
  /** Number of rows per page (controlled) */
  pageSize: number;
  /** Handler that is called when the page size changes. */
  onPageSizeChange: (pageSize: number) => void;
}

export interface PaginationClientSideProps {
  /** Whether the previous page is available (if not, the go to previous page button should be disabled).	*/
  enablePrevPage?: never;
  /** Whether the next page is available (if not, the go to next page button should be disabled). */
  enableNextPage?: never;
}

export interface PaginationServerSideProps {
  /** Whether the previous page is available (if not, the go to previous page button should be disabled).	*/
  enablePrevPage: boolean;
  /** Whether the next page is available (if not, the go to next page button should be disabled). */
  enableNextPage: boolean;
}
// #endregion Types

/**
 * Rounds the given page size to the nearest option, to avoid invalid page sizes.
 *
 * @param pageSize - the given page size
 * @param pageSizeOptions - the available page sizes
 */
export function sanitizePageSize(
  pageSize: number,
  pageSizeOptions: number[],
): number {
  return pageSizeOptions.reduce(function (
    prevOption: number,
    currOption: number,
  ) {
    return Math.abs(currOption - pageSize) <= Math.abs(prevOption - pageSize)
      ? currOption
      : prevOption;
  });
}

/**
 * Pagination component, used inside the table.
 */
export const Pagination = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  PaginationProps
>((props, forwardedRef) => {
  const tablePaginationContext = useContext(TablePaginationContext);
  const {
    enablePrevPage,
    enableNextPage,
    pageSize: pageSizeProp,
    pageIndex: pageIndexProp,
    onPageSizeChange,
    onPageChange,
    onPageIndexChange,
    'data-testid': dataTestId,
  } = props;

  const isControlledPageSize = pageSizeProp !== undefined;
  const isControlledPageIndex = pageIndexProp !== undefined;
  const smallScreen = useBreakpoint(`(max-width: ${Breakpoints.Max.Mobile}px)`);

  const [pageSize, setPageSize] = _useControllableState<number>({
    defaultValue:
      tablePaginationContext.pageSize ?? DEFAULT_PAGINATION_PAGE_SIZE,
    value: pageSizeProp,
    onChange: onPageSizeChange,
  });

  const [pageIndex, setPageIndex] = _useControllableState<number>({
    defaultValue:
      tablePaginationContext.pageIndex || DEFAULT_PAGINATION_PAGE_INDEX,
    value: pageIndexProp,
  });

  const updatePageSize = (newPageSize: number) => {
    setPageSize(newPageSize);
    isControlledPageIndex
      ? onPageChange?.(newPageSize, pageIndex)
      : updatePageIndex(DEFAULT_PAGINATION_PAGE_INDEX, 'internal', newPageSize);
  };

  const updatePageIndex = (
    newPageIndex: number,
    trigger: 'user' | 'internal' = 'user',
    currentPageSize: number | undefined = pageSize,
  ) => {
    setPageIndex(newPageIndex);
    onPageIndexChange?.(newPageIndex, trigger);
    onPageChange?.(currentPageSize, newPageIndex);
  };

  const pageSizeBase = DEFAULT_PAGINATION_PAGE_SIZE;
  const maxNumberOfEntries = pageSize * tablePaginationContext.pageCount;
  // generate page size options from base and filter relevant options
  const pageSizeOptions = [
    pageSizeBase,
    pageSizeBase * 2,
    pageSizeBase * 3,
    pageSizeBase * 4,
    pageSizeBase * 5,
  ].filter((option, i) =>
    tablePaginationContext.manualPagination || i === 0
      ? true
      : option - pageSizeBase < maxNumberOfEntries,
  );
  const sanitizedPageSize = sanitizePageSize(pageSize, pageSizeOptions);

  const prevPageSize = useRef(pageSize);
  const prevPageIndex = useRef(pageIndex);
  const prevData = useRef(tablePaginationContext.data);
  const intl = useIntl();

  // update page size in table state when it has changed
  if (prevPageSize.current !== pageSize) {
    Promise.resolve().then(() => tablePaginationContext.setPageSize(pageSize));
    prevPageSize.current = pageSize;
  }

  // update page index in table state when it has changed
  if (prevPageIndex.current !== pageIndex) {
    Promise.resolve().then(() =>
      tablePaginationContext.setPageIndex(pageIndex),
    );
    prevPageIndex.current = pageIndex;
  }

  // update page size if its not in line with the possible options
  if (!isControlledPageSize && sanitizedPageSize !== pageSize) {
    Promise.resolve().then(() => updatePageSize(sanitizedPageSize));
  }

  // move to the first page if there are no more entries on the current page
  if (
    !isControlledPageIndex &&
    !tablePaginationContext.manualPagination &&
    pageIndex >= tablePaginationContext.pageCount
  ) {
    Promise.resolve().then(() =>
      updatePageIndex(DEFAULT_PAGINATION_PAGE_INDEX, 'internal'),
    );
  }

  // reset page page index if data changed with client-side uncontrolled pagination
  if (
    !tablePaginationContext.manualPagination &&
    !isControlledPageIndex &&
    JSON.stringify(prevData.current) !==
      JSON.stringify(tablePaginationContext.data)
  ) {
    Promise.resolve().then(() =>
      updatePageIndex(DEFAULT_PAGINATION_PAGE_INDEX, 'internal'),
    );
    prevData.current = tablePaginationContext.data;
  }

  return (
    <Flex
      data-testid={dataTestId}
      ref={forwardedRef}
      justifyContent="space-between"
      flexWrap="wrap"
      alignItems="center"
      className="strato-table-pagination"
      role="navigation"
      aria-label={intl.formatMessage(dataTableMessages.paginationControls)}
    >
      <PageSizeSelect
        pageSizeOptions={pageSizeOptions}
        onChange={updatePageSize}
      />
      <Flex gap={16}>
        {!tablePaginationContext.manualPagination && (
          <PageIndexSelect onChange={updatePageIndex} />
        )}
        {(!smallScreen || tablePaginationContext.manualPagination) && (
          <PrevNextButtons
            updatePageIndex={updatePageIndex}
            enablePrevPage={enablePrevPage}
            enableNextPage={enableNextPage}
          />
        )}
      </Flex>
    </Flex>
  );
});

(Pagination as typeof Pagination & { displayName: string }).displayName =
  'Pagination';
